def max_fill(grid: List[List[int]], capacity: int) -> int:
    fibfib = [0, 1]
    for i in range(2, len(grid) + 1):
        fibfib.append(fibfib[i - 1] + fibfib[i - 2] + fibfib[i - 3])

    total_fills = 0
    for i, row in enumerate(grid):
        ones_count = sum(row)
        if ones_count > 0:
            fills_needed = fibfib[i]
            total_fills += (ones_count + capacity - 1) // capacity * fills_needed

    return total_fills
