from typing import List, Dict, Tuple
import math

def factorize(n: int) -> Dict[int, Tuple[int, int]]:
    """Return a dictionary of prime factors with their counts and positions in the factorization sequence.
    The dictionary keys are prime factors, and values are tuples of (count, position_sum).
    Position_sum is the sum of positions where the factor appears in the sequence.
    >>> factorize(8)
    {2: (3, 6)}
    >>> factorize(25)
    {5: (2, 3)}
    >>> factorize(70)
    {2: (1, 1), 5: (1, 2), 7: (1, 3)}
    """
    factors = {}
    i = 2
    position = 1

    while i <= int(math.sqrt(n) + 1):
        if n % i == 0:
            if i in factors:
                factors[i] = (factors[i][0] + 1, factors[i][1] + position)
            else:
                factors[i] = (1, position)
            n //= i
            position += 1
        else:
            i += 1

    if n > 1:
        if n in factors:
            factors[n] = (factors[n][0] + 1, factors[n][1] + position)
        else:
            factors[n] = (1, position)

    return factors

