def get_complex_vowel_power(word):
    """Enhanced version combining original vowel logic with power of 2 checks:
    - Finds the closest vowel (case sensitive) between two consonants from right of word
      (vowels at first/last char excluded).
    - Instead of returning that vowel, returns the vowel's 1-based index **only if** the 
      index itself is a simple power of 2.
    - Otherwise returns -1.
    - If no vowel matches original condition, returns -1.

    This adds complexity by integrating numeric power logic into vowel position validation.
    """
    if len(word) < 3:
        return -1

    vowels = {"a", "e", "i", "o", "u", "A", "E", 'O', 'U', 'I'}

    def is_power_of_2(x):
        if x < 1:
            return False
        while x % 2 == 0:
            x //= 2
        return x == 1

    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            if (word[i - 1] not in vowels) and (word[i + 1] not in vowels):
                # Check if position (1-based) is simple power of 2
                pos = i + 1
                if is_power_of_2(pos):
                    return pos
                else:
                    return -1
    return -1

