    return False

month = int(mm)
day = int(dd)
year = int(yyyy)

if year <= 0 or not (1 <= month <= 12):
    return False

# Determine max day for the month considering leap year
if month in [1, 3, 5, 7, 8, 10, 12]:
    max_day = 31
elif month in [4, 6, 9, 11]:
    max_day = 30
elif month == 2:
    # Leap year check
    if (year % 400 == 0) or (year % 4 == 0 and year % 100 != 0):
        max_day = 29
    else:
        max_day = 28
else:
