def sort_array(arr):
    def factorize(n):
        import math
        fact = []
        i = 2
        while i <= int(math.sqrt(n)) + 1:
            if n % i == 0:
                fact.append(i)
                n //= i
            else:
                i += 1
        if n > 1:
            fact.append(n)
        return fact

    arr_sorted = sorted(arr, key=lambda x: (len(factorize(abs(x))), x))
    return arr_sorted

