def largest_smallest_integers(lst):
    def greatest_common_divisor(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    def compute_gcd(numbers):
        if not numbers:
            return None
        current_gcd = abs(numbers[0])
        for num in numbers[1:]:
            current_gcd = greatest_common_divisor(current_gcd, abs(num))
            if current_gcd == 1:
                break
        return current_gcd

    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]

    gcd_neg = compute_gcd(negatives) if negatives else None
    sum_pos = sum(positives) if positives else 0

    return (gcd_neg, sum_pos)

