def order_by_points(nums):
    def digits_sum(n: int) -> int:
        neg = 1
        if n < 0:
            n, neg = -1 * n, -1
        n = [int(i) for i in str(n)]
        n[0] = n[0] * neg
        return sum(n)

    if not nums:
        return None

    sorted_nums = sorted(nums, key=digits_sum)

    max_digit_sum = max(digits_sum(x) for x in sorted_nums)

    result = None
    for x in sorted_nums:
        if digits_sum(x) == max_digit_sum:
            if result is None or len(str(abs(x))) > len(str(abs(result))):
                result = x
            elif len(str(abs(x))) == len(str(abs(result))):
                result = result  # keep first occurrence in sorted order

    return result

