def unique_digits(x):
    """Process list x to return sorted list of computed values based on digit conditions and index."""
    result = []
    for idx, num in enumerate(x):
        # Check if all digits are odd
        if all(int(c) % 2 == 1 for c in str(num)):
            # Determine if index is even or odd
            if idx % 2 == 0:
                # Compute factorial of the number
                fact = 1
                for i in range(1, num + 1):
                    fact *= i
                result.append(fact)
            else:
                # Compute sum of digits
                digit_sum = sum(int(c) for c in str(num))
                result.append(digit_sum)
    return sorted(result)

