        if x in (2, 3):
            return True
        if x % 2 == 0:
            return False
        r = int(x**0.5)
        for i in range(3, r + 1, 2):
            if x % i == 0:
                return False
        return True

    def collatz_odds(start: int) -> List[int]:
        result = []
        x = start
        while x != 1:
            if x % 2 == 1:
                result.append(x)
            if x % 2 == 0:
                x = x // 2
            else:
                x = 3 * x + 1
        result.append(1)
        # Remove duplicates but preserve order:
        seen = set()
        unique = []
        for num in result:
            if num not in seen:
                seen.add(num)
                unique.append(num)
        return unique

    res: Dict[int, List[int]] = {}
    for p in range(2, n):
        if is_prime(p):
            res[p] = collatz_odds(p)
    return res
